{"content": "#include "kernel_operator.h"
#include <cmath>

using namespace AscendC;

constexpr int BUFFER_NUM = 2;

struct TilingData {
    int64_t n;
    int64_t m;
    int64_t mode;
    int64_t blockN;
    int64_t blockM;
    int64_t nNum;
    int64_t mNum;
    int64_t totalBlocks;
    int64_t usedCoreNum;
    int64_t tasksPerCore;
    int64_t tileLength;
    int64_t dtypeSize;
};


template <typename T>
class KernelIoU {
public:
    __aicore__ inline KernelIoU() {}

    __aicore__ inline void Init(GM_ADDR bboxes, GM_ADDR gtboxes, GM_ADDR output,
                                TilingData* tiling, AscendC::TPipe* pipe) {
        tilingData = *tiling;

        int64_t n = tilingData.n;
        int64_t m = tilingData.m;

        bboxesGm.SetGlobalBuffer((__gm__ T*)bboxes, n * 4);
        gtboxesGm.SetGlobalBuffer((__gm__ T*)gtboxes, m * 4);
        outputGm.SetGlobalBuffer((__gm__ T*)output, m * n);

        // UB buffer sizes
        int64_t blockN = tilingData.blockN;
        int64_t blockM = tilingData.blockM;

        // bbox tile: [blockN, 4]
        pipe->InitBuffer(bboxQueue, BUFFER_NUM, blockN * 4 * sizeof(T));
        // gtbox tile: [blockM, 4]
        pipe->InitBuffer(gtQueue, BUFFER_NUM, blockM * 4 * sizeof(T));
        // inter tile: [blockM, blockN]
        pipe->InitBuffer(interQueue, BUFFER_NUM, blockM * blockN * sizeof(T));
        // result tile: [blockM, blockN]
        pipe->InitBuffer(outQueue, BUFFER_NUM, blockM * blockN * sizeof(T));
        // area1: [blockN]
        pipe->InitBuffer(area1Queue, BUFFER_NUM, blockN * sizeof(T));
        // area2: [blockM]
        pipe->InitBuffer(area2Queue, BUFFER_NUM, blockM * sizeof(T));
        // temp row buffer: [blockN]
        pipe->InitBuffer(tmpQueue, BUFFER_NUM, blockN * sizeof(T));
    }

    __aicore__ inline void Process() {
        int64_t totalBlocks = tilingData.totalBlocks;
        int64_t usedCoreNum = tilingData.usedCoreNum;
        int64_t tasksPerCore = tilingData.tasksPerCore;
        int64_t nNum = tilingData.nNum;
        int64_t mNum = tilingData.mNum;
        int64_t n = tilingData.n;
        int64_t m = tilingData.m;
        int64_t blockN = tilingData.blockN;
        int64_t blockM = tilingData.blockM;

        int64_t coreIdx = GetBlockIdx();

        for (int64_t localIdx = 0; localIdx < tasksPerCore; localIdx++) {
            int64_t blockIdx = coreIdx * tasksPerCore + localIdx;
            if (blockIdx >= totalBlocks) {
                continue;
            }

            int64_t bx = blockIdx / mNum;
            int64_t by = blockIdx % mNum;

            int64_t nStart = bx * blockN;
            int64_t mStart = by * blockM;
            int64_t nEnd = (nStart + blockN < n) ? (nStart + blockN) : n;
            int64_t mEnd = (mStart + blockM < m) ? (mStart + blockM) : m;
            int64_t curN = nEnd - nStart;
            int64_t curM = mEnd - mStart;

            if (curN <= 0 || curM <= 0) {
                continue;
            }

            // CopyIn bboxes tile
            CopyInBboxes(nStart, curN);
            // CopyIn gtboxes tile
            CopyInGtboxes(mStart, curM);
            // Compute
            Compute(curN, curM, nStart, mStart);
            // CopyOut result
            CopyOut(curN, curM, nStart, mStart);
        }
    }

private:
    __aicore__ inline void CopyInBboxes(int64_t nStart, int64_t curN) {
        LocalTensor<T> bboxLocal = bboxQueue.AllocTensor<T>();
        DataCopyPad(bboxLocal, bboxesGm[nStart * 4], {1, (uint32_t)(curN * 4 * sizeof(T)), 0, 0});
        bboxQueue.EnQue(bboxLocal);
    }

    __aicore__ inline void CopyInGtboxes(int64_t mStart, int64_t curM) {
        LocalTensor<T> gtLocal = gtQueue.AllocTensor<T>();
        DataCopyPad(gtLocal, gtboxesGm[mStart * 4], {1, (uint32_t)(curM * 4 * sizeof(T)), 0, 0});
        gtQueue.EnQue(gtLocal);
    }

    __aicore__ inline void Compute(int64_t curN, int64_t curM, int64_t nStart, int64_t mStart) {
        LocalTensor<T> bboxLocal = bboxQueue.DeQue<T>();
        LocalTensor<T> gtLocal = gtQueue.DeQue<T>();

        int64_t blockN = tilingData.blockN;
        int64_t blockM = tilingData.blockM;
        int64_t mode = tilingData.mode;

        // Compute area1 for each bbox: (x2-x1) * (y2-y1)
        LocalTensor<T> area1Local = area1Queue.AllocTensor<T>();
        for (int64_t j = 0; j < curN; j++) {
            T x1 = bboxLocal.GetValue(j * 4 + 0);
            T y1 = bboxLocal.GetValue(j * 4 + 1);
            T x2 = bboxLocal.GetValue(j * 4 + 2);
            T y2 = bboxLocal.GetValue(j * 4 + 3);
            T w = x2 - x1;
            T h = y2 - y1;
            area1Local.SetValue(j, w * h);
        }
        area1Queue.EnQue(area1Local);

        // Compute area2 for each gtbox: (x2-x1) * (y2-y1)
        LocalTensor<T> area2Local = area2Queue.AllocTensor<T>();
        for (int64_t i = 0; i < curM; i++) {
            T x1 = gtLocal.GetValue(i * 4 + 0);
            T y1 = gtLocal.GetValue(i * 4 + 1);
            T x2 = gtLocal.GetValue(i * 4 + 2);
            T y2 = gtLocal.GetValue(i * 4 + 3);
            T w = x2 - x1;
            T h = y2 - y1;
            area2Local.SetValue(i, w * h);
        }
        area2Queue.EnQue(area2Local);

        // Compute intersection for each pair
        LocalTensor<T> interLocal = interQueue.AllocTensor<T>();

        for (int64_t i = 0; i < curM; i++) {
            T gtx1 = gtLocal.GetValue(i * 4 + 0);
            T gty1 = gtLocal.GetValue(i * 4 + 1);
            T gtx2 = gtLocal.GetValue(i * 4 + 2);
            T gty2 = gtLocal.GetValue(i * 4 + 3);

            for (int64_t j = 0; j < curN; j++) {
                T bx1 = bboxLocal.GetValue(j * 4 + 0);
                T by1 = bboxLocal.GetValue(j * 4 + 1);
                T bx2 = bboxLocal.GetValue(j * 4 + 2);
                T by2 = bboxLocal.GetValue(j * 4 + 3);

                T ltX = (bx1 > gtx1) ? bx1 : gtx1;
                T ltY = (by1 > gty1) ? by1 : gty1;
                T rbX = (bx2 < gtx2) ? bx2 : gtx2;
                T rbY = (by2 < gty2) ? by2 : gty2;

                T whX = rbX - ltX;
                T whY = rbY - ltY;
                if (whX < (T)0) whX = (T)0;
                if (whY < (T)0) whY = (T)0;

                T inter = whX * whY;
                interLocal.SetValue(i * blockN + j, inter);
            }
        }
        interQueue.EnQue(interLocal);

        // Compute IoU/IoF matrix
        LocalTensor<T> resultLocal = outQueue.AllocTensor<T>();
        LocalTensor<T> area1Deq = area1Queue.DeQue<T>();
        LocalTensor<T> area2Deq = area2Queue.DeQue<T>();
        LocalTensor<T> interDeq = interQueue.DeQue<T>();

        T eps = (T)1e-10;

        for (int64_t i = 0; i < curM; i++) {
            for (int64_t j = 0; j < curN; j++) {
                T inter = interDeq.GetValue(i * blockN + j);
                T a1 = area1Deq.GetValue(j);
                T a2 = area2Deq.GetValue(i);

                T denom;
                if (mode == 0) {
                    // IoU: inter / (area1 + area2 - inter)
                    denom = a1 + a2 - inter;
                    if (denom < eps) denom = eps;
                } else {
                    // IoF: inter / area2
                    denom = a2;
                    if (denom < eps) denom = eps;
                }

                T iou = inter / denom;
                resultLocal.SetValue(i * blockN + j, iou);
            }
        }

        outQueue.EnQue(resultLocal);

        // Free tensors
        bboxQueue.FreeTensor(bboxLocal);
        gtQueue.FreeTensor(gtLocal);
        area1Queue.FreeTensor(area1Deq);
        area2Queue.FreeTensor(area2Deq);
        interQueue.FreeTensor(interDeq);
    }

    __aicore__ inline void CopyOut(int64_t curN, int64_t curM, int64_t nStart, int64_t mStart) {
        LocalTensor<T> resultLocal = outQueue.DeQue<T>();
        int64_t n = tilingData.n;
        int64_t blockN = tilingData.blockN;

        for (int64_t i = 0; i < curM; i++) {
            int64_t dstOffset = (mStart + i) * n + nStart;
            DataCopyPad(outputGm[dstOffset], resultLocal[i * blockN], {1, (uint32_t)(curN * sizeof(T)), 0, 0});
        }
        outQueue.FreeTensor(resultLocal);
    }

private:
    TPipe pipe;
    TQue<QuePosition::VECIN, BUFFER_NUM> bboxQueue;
    TQue<QuePosition::VECIN, BUFFER_NUM> gtQueue;
    TQue<QuePosition::VECIN, BUFFER_NUM> interQueue;
    TQue<QuePosition::VECOUT, BUFFER_NUM> outQueue;
    TQue<QuePosition::VECIN, BUFFER_NUM> area1Queue;
    TQue<QuePosition::VECIN, BUFFER_NUM> area2Queue;
    TQue<QuePosition::VECIN, BUFFER_NUM> tmpQueue;

    GlobalTensor<T> bboxesGm;
    GlobalTensor<T> gtboxesGm;
    GlobalTensor<T> outputGm;

    TilingData tilingData;
};


extern "C" __global__ __aicore__ void iou(GM_ADDR bboxes, GM_ADDR gtboxes, GM_ADDR output, TilingData* tiling) {
    AscendC::TPipe pipe;
    if (tiling->dtypeSize == 4) {
        KernelIoU<float> op;
        op.Init(bboxes, gtboxes, output, tiling, &pipe);
        op.Process();
    } else {
        KernelIoU<half> op;
        op.Init(bboxes, gtboxes, output, tiling, &pipe);
        op.Process();
    }
}
