{"content": "#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"
#include "aclrtlaunch_iou.h"
#include <torch/library.h>

namespace ascend_kernel {

at::Tensor iou(const at::Tensor& bboxes, const at::Tensor& gtboxes, int64_t mode) {
    // Input validation
    TORCH_CHECK(bboxes.dim() == 2, "bboxes must be 2D tensor");
    TORCH_CHECK(gtboxes.dim() == 2, "gtboxes must be 2D tensor");
    TORCH_CHECK(bboxes.size(1) == 4, "bboxes must have shape [N, 4]");
    TORCH_CHECK(gtboxes.size(1) == 4, "gtboxes must have shape [M, 4]");
    TORCH_CHECK(mode == 0 || mode == 1, "mode must be 0 (IoU) or 1 (IoF)");

    int64_t n = bboxes.size(0);
    int64_t m = gtboxes.size(0);

    // Create output tensor [m, n]
    auto output = at::empty({m, n}, bboxes.options());

    // Get platform info
    auto ascendc_platform = platform_ascendc::PlatformAscendCManager::GetInstance();
    int64_t coreNum = static_cast<int64_t>(ascendc_platform->GetCoreNumAiv());
    uint64_t ubSize;
    ascendc_platform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);

    // Block-level tiling
    int64_t blockN = 64;
    int64_t blockM = 64;

    int64_t nNum = (n + blockN - 1) / blockN;
    int64_t mNum = (m + blockM - 1) / blockM;
    int64_t totalBlocks = nNum * mNum;
    int64_t usedCoreNum = std::min(coreNum, totalBlocks);
    int64_t tasksPerCore = (totalBlocks + usedCoreNum - 1) / usedCoreNum;

    // UB-level tiling: compute tileLength based on bufferCoefficient
    int64_t dtypeSize = (bboxes.dtype() == at::kFloat) ? 4 : 2;
    int64_t bufferCoefficient = (dtypeSize == 4) ? 32 : 24; // multi-input with intermediate buffers

    int64_t tileLength = (ubSize / bufferCoefficient) / dtypeSize;
    tileLength = (tileLength / 32) * 32; // 32B align
    if (tileLength < 32) tileLength = 32;

    // TilingData
    struct TilingData {
        int64_t n;
        int64_t m;
        int64_t mode;
        int64_t blockN;
        int64_t blockM;
        int64_t nNum;
        int64_t mNum;
        int64_t totalBlocks;
        int64_t usedCoreNum;
        int64_t tasksPerCore;
        int64_t tileLength;
        int64_t dtypeSize;
    } tilingData;

    tilingData.n = n;
    tilingData.m = m;
    tilingData.mode = mode;
    tilingData.blockN = blockN;
    tilingData.blockM = blockM;
    tilingData.nNum = nNum;
    tilingData.mNum = mNum;
    tilingData.totalBlocks = totalBlocks;
    tilingData.usedCoreNum = usedCoreNum;
    tilingData.tasksPerCore = tasksPerCore;
    tilingData.tileLength = tileLength;
    tilingData.dtypeSize = dtypeSize;

    int64_t blockDim = usedCoreNum;

    // EXEC_KERNEL_CMD: all args must be lvalues
    EXEC_KERNEL_CMD(iou, blockDim, bboxes, gtboxes, output, tilingData);

    return output;
}

} // namespace ascend_kernel
