6	constexpr int BUFFER_NUM = 2;
7	
8	struct TilingData {
9	    int64_t n;
10	    int64_t m;
11	    int64_t mode;
12	    int64_t blockN;
13	    int64_t blockM;
14	    int64_t nNum;
15	    int64_t mNum;
16	    int64_t totalBlocks;
17	    int64_t usedCoreNum;
18	    int64_t tasksPerCore;
19	    int64_t tileLength;
20	    int64_t dtypeSize;
21	};
22	
23	
24	template <typename T>
25	class KernelIoU {
26	public:
27	    __aicore__ inline KernelIoU() {}
28	
29	    __aicore__ inline void Init(GM_ADDR bboxes, GM_ADDR gtboxes, GM_ADDR output,
30	                                TilingData* tiling, AscendC::TPipe* pipe) {
31	        tilingData = *tiling;
32	
33	        int64_t n = tilingData.n;
34	        int64_t m = tilingData.m;
35	
36	        bboxesGm.SetGlobalBuffer((__gm__ T*)bboxes, n * 4);
37	        gtboxesGm.SetGlobalBuffer((__gm__ T*)gtboxes, m * 4);
38	        outputGm.SetGlobalBuffer((__gm__ T*)output, m * n);
39	
40	        // UB buffer sizes
41	        int64_t blockN = tilingData.blockN;
42	        int64_t blockM = tilingData.blockM;
43	
44	        // bbox tile: [blockN, 4]
45	        pipe->InitBuffer(bboxQueue, BUFFER_NUM, blockN * 4 * sizeof(T));
46	        // gtbox tile: [blockM, 4]
47	        pipe->InitBuffer(gtQueue, BUFFER_NUM, blockM * 4 * sizeof(T));
48	        // inter tile: [blockM, blockN]
49	        pipe->InitBuffer(interQueue, BUFFER_NUM, blockM * blockN * sizeof(T));
50	        // result tile: [blockM, blockN]
51	        pipe->InitBuffer(outQueue, BUFFER_NUM, blockM * blockN * sizeof(T));
52	        // area1: [blockN]
53	        pipe->InitBuffer(area1Queue, BUFFER_NUM, blockN * sizeof(T));
54	        // area2: [blockM]
55	        pipe->InitBuffer(area2Queue, BUFFER_NUM, blockM * sizeof(T));
56	        // temp row buffer: [blockN]
57	        pipe->InitBuffer(tmpQueue, BUFFER_NUM, blockN * sizeof(T));
58	    }
59	
60	    __aicore__ inline void Process() {
61	        int64_t totalBlocks = tilingData.totalBlocks;
62	        int64_t usedCoreNum = tilingData.usedCoreNum;
63	        int64_t tasksPerCore = tilingData.tasksPerCore;
64	        int64_t nNum = tilingData.nNum;
65	        int64_t mNum = tilingData.mNum;
66	        int64_t n = tilingData.n;
67	        int64_t m = tilingData.m;
68	        int64_t blockN = tilingData.blockN;
69	        int64_t blockM = tilingData.blockM;
70	
71	        int64_t coreIdx = GetBlockIdx();
72	
73	        for (int64_t localIdx = 0; localIdx < tasksPerCore; localIdx++) {
74	            int64_t blockIdx = coreIdx * tasksPerCore + localIdx;
75	            if (blockIdx >= totalBlocks) {
76	                continue;
77	            }
78	
79	            int64_t bx = blockIdx / mNum;
80	            int64_t by = blockIdx % mNum;
81	
82	            int64_t nStart = bx * blockN;
83	            int64_t mStart = by * blockM;
84	            int64_t nEnd = (nStart + blockN < n) ? (nStart + blockN) : n;
85	            int64_t mEnd = (mStart + blockM < m) ? (mStart + blockM) : m;
86	            int64_t curN = nEnd - nStart;
87	            int64_t curM = mEnd - mStart;
88	
89	            if (curN <= 0 || curM <= 0) {
90	                continue;
91	            }
92	
93	            // CopyIn bboxes tile
94	            CopyInBboxes(nStart, curN);
95	            // CopyIn gtboxes tile
96	            CopyInGtboxes(mStart, curM);
97	            // Compute
98	            Compute(curN, curM, nStart, mStart);
99	            // CopyOut result
100	            CopyOut(curN, curM, nStart, mStart);
101	        }
102	    }
103	
104	private:
105	    __aicore__ inline void CopyInBboxes(int64_t nStart, int64_t curN) {
106	        LocalTensor<T> bboxLocal = bboxQueue.AllocTensor<T>();
107	        DataCopyPad(bboxLocal, bboxesGm[nStart * 4], {1, (uint32_t)(curN * 4 * sizeof(T)), 0, 0});
108	        bboxQueue.EnQue(bboxLocal);
109	    }
110	
111	    __aicore__ inline void CopyInGtboxes(int64_t mStart, int64_t curM) {
112	        LocalTensor<T> gtLocal = gtQueue.AllocTensor<T>();
113	        DataCopyPad(gtLocal, gtboxesGm[mStart * 4], {1, (uint32_t)(curM * 4 * sizeof(T)), 0, 0});
114	        gtQueue.EnQue(gtLocal);
115	    }
116	
117	    __aicore__ inline void Compute(int64_t curN, int64_t curM, int64_t nStart, int64_t mStart) {
118	        LocalTensor<T> bboxLocal = bboxQueue.DeQue<T>();
119	        LocalTensor<T> gtLocal = gtQueue.DeQue<T>();
120	
121	        int64_t blockN = tilingData.blockN;
122	        int64_t blockM = tilingData.blockM;
123	        int64_t mode = tilingData.mode;
124	
125	        // Compute area1 for each bbox: (x2-x1) * (y2-y1)
126	        LocalTensor<T> area1Local = area1Queue.AllocTensor<T>();
127	        for (int64_t j = 0; j < curN; j++) {
128	            T x1 = bboxLocal.GetValue(j * 4 + 0);
129	            T y1 = bboxLocal.GetValue(j * 4 + 1);
130	            T x2 = bboxLocal.GetValue(j * 4 + 2);
131	            T y2 = bboxLocal.GetValue(j * 4 + 3);
132	            T w = x2 - x1;
133	            T h = y2 - y1;
134	            area1Local.SetValue(j, w * h);
135	        }
136	        area1Queue.EnQue(area1Local);
137	
138	        // Compute area2 for each gtbox: (x2-x1) * (y2-y1)
139	        LocalTensor<T> area2Local = area2Queue.AllocTensor<T>();
140	        for (int64_t i = 0; i < curM; i++) {
141	            T x1 = gtLocal.GetValue(i * 4 + 0);
142	            T y1 = gtLocal.GetValue(i * 4 + 1);
143	            T x2 = gtLocal.GetValue(i * 4 + 2);
144	            T y2 = gtLocal.GetValue(i * 4 + 3);
145	            T w = x2 - x1;
146	            T h = y2 - y1;
147	            area2Local.SetValue(i, w * h);
148	        }
149	        area2Queue.EnQue(area2Local);
150	
151	        // Compute intersection for each pair
152	        LocalTensor<T> interLocal = interQueue.AllocTensor<T>();
153	
154	        for (int64_t i = 0; i < curM; i++) {
155	            T gtx1 = gtLocal.GetValue(i * 4 + 0);
156	            T gty1 = gtLocal.GetValue(i * 4 + 1);
157	            T gtx2 = gtLocal.GetValue(i * 4 + 2);
158	            T gty2 = gtLocal.GetValue(i * 4 + 3);
159	
160	            for (int64_t j = 0; j < curN; j++) {
161	                T bx1 = bboxLocal.GetValue(j * 4 + 0);
162	                T by1 = bboxLocal.GetValue(j * 4 + 1);
163	                T bx2 = bboxLocal.GetValue(j * 4 + 2);
164	                T by2 = bboxLocal.GetValue(j * 4 + 3);
165	
166	                T ltX = (bx1 > gtx1) ? bx1 : gtx1;
167	                T ltY = (by1 > gty1) ? by1 : gty1;
168	                T rbX = (bx2 < gtx2) ? bx2 : gtx2;
169	                T rbY = (by2 < gty2) ? by2 : gty2;
170	
171	                T whX = rbX - ltX;
172	                T whY = rbY - ltY;
173	                if (whX < (T)0) whX = (T)0;
174	                if (whY < (T)0) whY = (T)0;
175	
176	                T inter = whX * whY;
177	                interLocal.SetValue(i * blockN + j, inter);
178	            }
179	        }
180	        interQueue.EnQue(interLocal);
181	
182	        // Compute IoU/IoF matrix
183	        LocalTensor<T> resultLocal = outQueue.AllocTensor<T>();
184	        LocalTensor<T> area1Deq = area1Queue.DeQue<T>();
185	        LocalTensor<T> area2Deq = area2Queue.DeQue<T>();
186	        LocalTensor<T> interDeq = interQueue.DeQue<T>();
187	
188	        T eps = (T)1e-10;
189	
190	        for (int64_t i = 0; i < curM; i++) {
191	            for (int64_t j = 0; j < curN; j++) {
192	                T inter = interDeq.GetValue(i * blockN + j);
193	                T a1 = area1Deq.GetValue(j);
194	                T a2 = area2Deq.GetValue(i);
195	
196	                T denom;
197	                if (mode == 0) {
198	                    // IoU: inter / (area1 + area2 - inter)
199	                    denom = a1 + a2 - inter;
200	                    if (denom < eps) denom = eps;
201	                } else {
202	                    // IoF: inter / area2
203	                    denom = a2;
204	                    if (denom < eps) denom = eps;
205	                }
206	
207	                T iou = inter / denom;
208	                resultLocal.SetValue(i * blockN + j, iou);
209	            }
210	        }
211	
212	        outQueue.EnQue(resultLocal);
213	
214	        // Free tensors
215	        bboxQueue.FreeTensor(bboxLocal);
216	        gtQueue.FreeTensor(gtLocal);
217	        area1Queue.FreeTensor(area1Deq);
218	        area2Queue.FreeTensor(area2Deq);
219	        interQueue.FreeTensor(interDeq);
220	    }
221	
222	    __aicore__ inline void CopyOut(int64_t curN, int64_t curM, int64_t nStart, int64_t mStart) {
223	        LocalTensor<T> resultLocal = outQueue.DeQue<T>();
224	        int64_t n = tilingData.n;
225	        int64_t blockN = tilingData.blockN;
226	
227	        for (int64_t i = 0; i < curM; i++) {
228	            int64_t dstOffset = (mStart + i) * n + nStart;
229	            DataCopyPad(outputGm[dstOffset], resultLocal[i * blockN], {1, (uint32_t)(curN * sizeof(T)), 0, 0});
230	        }
231	        outQueue.FreeTensor(resultLocal);
232	    }
233	
234	private:
235	    TPipe pipe;
236	    TQue<QuePosition::VECIN, BUFFER_NUM> bboxQueue;
237	    TQue<QuePosition::VECIN, BUFFER_NUM> gtQueue;
238	    TQue<QuePosition::VECIN, BUFFER_NUM> interQueue;
