    AscendC::DataCopyPad(dst, src, copyParams);
}

template <typename T>
__aicore__ inline float GetFloatValue(AscendC::LocalTensor<T> &src, int idx) {
    if constexpr (std::is_same_v<T, float>) {
        return src.GetValue(idx);
    } else {
        return static_cast<float>(src.GetValue(idx));
    }
}

template <typename T>
__aicore__ inline void SetFloatValue(AscendC::LocalTensor<T> &dst, int idx, float val) {
    if constexpr (std::is_same_v<T, float>) {
        dst.SetValue(idx, val);
    } else {
        dst.SetValue(idx, static_cast<T>(val));
    }
}

template <typename T>
class KernelIoU {
public:
    __aicore__ inline KernelIoU() {}

    __aicore__ inline void Init(
        GM_ADDR bboxes, GM_ADDR gtboxes, GM_ADDR output,
        int64_t n, int64_t m, int64_t mode,
        int64_t blockN, int64_t blockM, int64_t nNum, int64_t mNum,
        int64_t totalBlocks, int64_t usedCoreNum, int64_t tasksPerCore,
        int64_t tileLength, int64_t dtypeSize) {

        this->n = n;
        this->m = m;
        this->mode = mode;
        this->blockN = blockN;
        this->blockM = blockM;
        this->nNum = nNum;
        this->mNum = mNum;
        this->totalBlocks = totalBlocks;
        this->usedCoreNum = usedCoreNum;
        this->tasksPerCore = tasksPerCore;
        this->tileLength = tileLength;
        this->dtypeSize = dtypeSize;

        bboxesGm.SetGlobalBuffer(reinterpret_cast<__gm__ T*>(bboxes), static_cast<uint64_t>(n) * 4);
        gtboxesGm.SetGlobalBuffer(reinterpret_cast<__gm__ T*>(gtboxes), static_cast<uint64_t>(m) * 4);
        outputGm.SetGlobalBuffer(reinterpret_cast<__gm__ T*>(output), static_cast<uint64_t>(m) * n);

        pipe.InitBuffer(bboxQueue, BUFFER_NUM, blockN * 4 * sizeof(T));
        pipe.InitBuffer(gtQueue, BUFFER_NUM, blockM * 4 * sizeof(T));
        pipe.InitBuffer(interQueue, BUFFER_NUM, blockM * blockN * sizeof(T));
        pipe.InitBuffer(outQueue, BUFFER_NUM, blockM * blockN * sizeof(T));
        pipe.InitBuffer(area1Queue, BUFFER_NUM, blockN * sizeof(T));
        pipe.InitBuffer(area2Queue, BUFFER_NUM, blockM * sizeof(T));
    }

    __aicore__ inline void Process() {
        int64_t coreIdx = GetBlockIdx();

        for (int64_t localIdx = 0; localIdx < tasksPerCore; localIdx++) {
            int64_t blockIdx = coreIdx * tasksPerCore + localIdx;
            if (blockIdx >= totalBlocks) {
                continue;
            }

            int64_t bx = blockIdx / mNum;
            int64_t by = blockIdx % mNum;

            int64_t nStart = bx * blockN;
            int64_t mStart = by * blockM;
            int64_t nEnd = (nStart + blockN < n) ? (nStart + blockN) : n;
            int64_t mEnd = (mStart + blockM < m) ? (mStart + blockM) : m;
            int64_t curN = nEnd - nStart;
            int64_t curM = mEnd - mStart;

            if (curN <= 0 || curM <= 0) {
                continue;
            }

            CopyInBboxes(nStart, curN);
            CopyInGtboxes(mStart, curM);
            Compute(curN, curM, nStart, mStart);
            CopyOut(curN, curM, nStart, mStart);
        }
    }

private:
    __aicore__ inline void CopyInBboxes(int64_t nStart, int64_t curN) {
        LocalTensor<T> bboxLocal = bboxQueue.AllocTensor<T>();
        LoadGmToUb(bboxLocal, bboxesGm[static_cast<uint64_t>(nStart) * 4], static_cast<uint32_t>(curN * 4));
        bboxQueue.EnQue(bboxLocal);
    }

    __aicore__ inline void CopyInGtboxes(int64_t mStart, int64_t curM) {
        LocalTensor<T> gtLocal = gtQueue.AllocTensor<T>();
        LoadGmToUb(gtLocal, gtboxesGm[static_cast<uint64_t>(mStart) * 4], static_cast<uint32_t>(curM * 4));
        gtQueue.EnQue(gtLocal);
    }

    __aicore__ inline void Compute(int64_t curN, int64_t curM, int64_t nStart, int64_t mStart) {
        LocalTensor<T> bboxLocal = bboxQueue.DeQue<T>();
        LocalTensor<T> gtLocal = gtQueue.DeQue<T>();

        // Compute area1 for each bbox: (x2-x1) * (y2-y1)
        LocalTensor<T> area1Local = area1Queue.AllocTensor<T>();
        for (int64_t j = 0; j < curN; j++) {
            float x1 = GetFloatValue(bboxLocal, j * 4 + 0);
            float y1 = GetFloatValue(bboxLocal, j * 4 + 1);
            float x2 = GetFloatValue(bboxLocal, j * 4 + 2);
            float y2 = GetFloatValue(bboxLocal, j * 4 + 3);
            float w = x2 - x1;
            float h = y2 - y1;
            SetFloatValue(area1Local, j, w * h);
        }
        area1Queue.EnQue(area1Local);

        // Compute area2 for each gtbox: (x2-x1) * (y2-y1)
        LocalTensor<T> area2Local = area2Queue.AllocTensor<T>();
        for (int64_t i = 0; i < curM; i++) {
            float x1 = GetFloatValue(gtLocal, i * 4 + 0);
            float y1 = GetFloatValue(gtLocal, i * 4 + 1);
            float x2 = GetFloatValue(gtLocal, i * 4 + 2);
            float y2 = GetFloatValue(gtLocal, i * 4 + 3);
            float w = x2 - x1;
            float h = y2 - y1;
            SetFloatValue(area2Local, i, w * h);
        }
        area2Queue.EnQue(area2Local);

        // Compute intersection for each pair
        LocalTensor<T> interLocal = interQueue.AllocTensor<T>();

        for (int64_t i = 0; i < curM; i++) {
            float gtx1 = GetFloatValue(gtLocal, i * 4 + 0);
            float gty1 = GetFloatValue(gtLocal, i * 4 + 1);
            float gtx2 = GetFloatValue(gtLocal, i * 4 + 2);
            float gty2 = GetFloatValue(gtLocal, i * 4 + 3);

            for (int64_t j = 0; j < curN; j++) {
                float bx1 = GetFloatValue(bboxLocal, j * 4 + 0);
                float by1 = GetFloatValue(bboxLocal, j * 4 + 1);
                float bx2 = GetFloatValue(bboxLocal, j * 4 + 2);
                float by2 = GetFloatValue(bboxLocal, j * 4 + 3);

                float ltX = (bx1 > gtx1) ? bx1 : gtx1;
                float ltY = (by1 > gty1) ? by1 : gty1;
                float rbX = (bx2 < gtx2) ? bx2 : gtx2;
                float rbY = (by2 < gty2) ? by2 : gty2;

                float whX = rbX - ltX;
                float whY = rbY - ltY;
                if (whX < 0.0f) whX = 0.0f;
                if (whY < 0.0f) whY = 0.0f;

                float inter = whX * whY;
                SetFloatValue(interLocal, i * blockN + j, inter);
            }
        }
        interQueue.EnQue(interLocal);

        // Compute IoU/IoF matrix
        LocalTensor<T> resultLocal = outQueue.AllocTensor<T>();
        LocalTensor<T> area1Deq = area1Queue.DeQue<T>();
        LocalTensor<T> area2Deq = area2Queue.DeQue<T>();
        LocalTensor<T> interDeq = interQueue.DeQue<T>();

        float eps = 1e-10f;

        for (int64_t i = 0; i < curM; i++) {
            for (int64_t j = 0; j < curN; j++) {
                float inter = GetFloatValue(interDeq, i * blockN + j);
                float a1 = GetFloatValue(area1Deq, j);
                float a2 = GetFloatValue(area2Deq, i);

                float denom;
                if (mode == 0) {
                    denom = a1 + a2 - inter;
                    if (denom < eps) denom = eps;
                } else {
                    denom = a2;
                    if (denom < eps) denom = eps;
                }

                float iou = inter / denom;
                SetFloatValue(resultLocal, i * blockN + j, iou);
            }
        }

        outQueue.EnQue(resultLocal);

        bboxQueue.FreeTensor(bboxLocal);
        gtQueue.FreeTensor(gtLocal);
        area1Queue.FreeTensor(area1Deq);
        area2Queue.FreeTensor(area2Deq);
        interQueue.FreeTensor(interDeq);
    }

    __aicore__ inline void CopyOut(int64_t curN, int64_t curM, int64_t nStart, int64_t mStart) {
        LocalTensor<T> resultLocal = outQueue.DeQue<T>();

        for (int64_t i = 0; i < curM; i++) {
            int64_t dstOffset = (mStart + i) * n + nStart;
            LocalTensor<T> srcSlice = resultLocal[static_cast<uint64_t>(i) * blockN];
            StoreUbToGm(outputGm[dstOffset], srcSlice, static_cast<uint32_t>(curN));
        }
        outQueue.FreeTensor(resultLocal);
    }

private:
    TPipe pipe;
    TQue<QuePosition::VECIN, BUFFER_NUM> bboxQueue;
    TQue<QuePosition::VECIN, BUFFER_NUM> gtQueue;
    TQue<QuePosition::VECIN, BUFFER_NUM> interQueue;
    TQue<QuePosition::VECOUT, BUFFER_NUM> outQueue;
    TQue<QuePosition::VECIN, BUFFER_NUM> area1Queue;
    TQue<QuePosition::VECIN, BUFFER_NUM> area2Queue;

    GlobalTensor<T> bboxesGm;
    GlobalTensor<T> gtboxesGm;
    GlobalTensor<T> outputGm;

    int64_t n = 0;
    int64_t m = 0;
    int64_t mode = 0;
    int64_t blockN = 64;
    int64_t blockM = 64;
    int64_t nNum = 0;
    int64_t mNum = 0;
    int64_t totalBlocks = 0;
    int64_t usedCoreNum = 0;
    int64_t tasksPerCore = 0;
    int64_t tileLength = 0;
    int64_t dtypeSize = 0;
};

extern "C" __global__ __aicore__ void iou(
    GM_ADDR bboxes, GM_ADDR gtboxes, GM_ADDR output,
    int64_t n, int64_t m, int64_t mode,
